//! C ABI for the Pathland GTK renderer (Java host).
//!
//! A foreign host (Java via JNA) drives the `pathland-native` flat world to
//! build/emit the retained tree, then calls `pathland_gtk_run` to hand the
//! renderer the shared ring and run GTK in-process. Raw-input events are
//! reported back through a C callback (`void (*)(u32 targetId)`).

use std::cell::RefCell;
use std::ffi::c_void;
use std::rc::Rc;

use pathland_native::NativeHost;
use pathland_transport::RingTransport;

use crate::run;

/// A host-supplied event callback: invoked with the activated node id.
pub type EventCallback = extern "C" fn(target_id: u32);

/// Run the GTK renderer over a `pathland_native` host's shared ring.
///
/// `host` is the opaque handle from `pathland_native_create`; the renderer
/// pumps its ring in-process (frames in, events out). `on_event` is called
/// (on the GTK main thread) with the id of the activated node; it may re-enter
/// `pathland_native_*` to update the tree and re-emit.
///
/// This function blocks until the GTK main loop exits (window closed).
#[no_mangle]
pub unsafe extern "C" fn pathland_gtk_run(
    host: *mut c_void,
    on_event: Option<EventCallback>,
) {
    if host.is_null() {
        return;
    }
    // Take the ring out of the NativeHost; the renderer owns it for the loop.
    // The host handle remains valid for Java to drive emits through it.
    let host_ref = &mut *(host as *mut NativeHost);
    // SAFETY: the renderer borrows the ring only within this call; Java must
    // not destroy the host until this returns.
    let ring = std::mem::replace(&mut host_ref.ring_mut(), RingTransport::new());

    let ring = Rc::new(RefCell::new(ring));
    let mut handler = move |event: pathland_opcode::Event, _ring: Rc<RefCell<RingTransport>>| {
        if let Some(cb) = on_event {
            if let pathland_opcode::Event::PointerUp { target, .. } = event {
                cb(target);
            }
        }
    };
    let _ = &mut handler;
    run("org.pathland.GtkDemo", "Pathland GTK Demo", ring, handler);

    // Restore the ring into the host before returning.
    // SAFETY: ring is dropped by the closure below; take the shared ref back.
    let _ = host_ref;
}

